package com.dy.artisan3d.utilimport androidx.compose.runtime.Composableimport android.app.Activityimport androidx.compose.material3.MaterialThemeimport androidx.compose.runtime.SideEffectimport androidx.compose.ui.graphics.toArgbimport androidx.compose.ui.platform.LocalViewimport androidx.core.view.WindowCompat@Composableactual fun PlatformSystemBars(darkTheme: Boolean) {    val view = LocalView.current    val colorScheme = MaterialTheme.colorScheme    if (!view.isInEditMode) {        SideEffect {            val window = (view.context as Activity).window            // Status bar fonini mavzu foniga moslash            window.statusBarColor = colorScheme.background.toArgb()            val insetsController = WindowCompat.getInsetsController(window, view)            // Agar light theme bo'lsa, ikonkalarni qora qiladi            insetsController.isAppearanceLightStatusBars = !darkTheme        }    }}